create table public.anonymous_questions(id uuid primary key default gen_random_uuid(),sender uuid not null references public.profiles(id),recipient uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 500),created_at timestamptz not null default now(),check(sender<>recipient));
alter table public.anonymous_questions enable row level security;
revoke all on public.anonymous_questions from anon,authenticated;
grant select(id,recipient,body,created_at) on public.anonymous_questions to authenticated;
grant insert(sender,recipient,body) on public.anonymous_questions to authenticated;
grant delete on public.anonymous_questions to authenticated;
create policy aq_read on public.anonymous_questions for select to authenticated using(recipient=auth.uid());
create policy aq_send on public.anonymous_questions for insert to authenticated with check(sender=auth.uid() and not exists(select 1 from public.blocks b where (b.actor=sender and b.target=recipient) or (b.actor=recipient and b.target=sender)));
create policy aq_delete on public.anonymous_questions for delete to authenticated using(recipient=auth.uid());
alter table public.profiles add column questions_enabled boolean not null default false;
grant update(questions_enabled) on public.profiles to authenticated;
create policy aq_opt_in on public.anonymous_questions as restrictive for insert to authenticated with check(exists(select 1 from public.profiles p where p.id=recipient and p.questions_enabled));
create table public.message_reactions(message uuid references public.messages(id) on delete cascade,actor uuid references public.profiles(id) on delete cascade,reaction text not null check(reaction in ('like','heart','laugh','wow')),primary key(message,actor));
alter table public.message_reactions enable row level security;
revoke all on public.message_reactions from anon,authenticated;
grant select,insert,delete on public.message_reactions to authenticated;
create policy mr_read on public.message_reactions for select to authenticated using(exists(select 1 from public.messages m where m.id=message and (m.sender=auth.uid() or m.recipient=auth.uid())));
create policy mr_add on public.message_reactions for insert to authenticated with check(actor=auth.uid() and exists(select 1 from public.messages m where m.id=message and (m.sender=auth.uid() or m.recipient=auth.uid())));
create policy mr_delete on public.message_reactions for delete to authenticated using(actor=auth.uid());